solution:
package main

import "fmt"

func Parity(n int) string {
	if n%2 == 0 {
		return "even"
	}
	return "odd"
}

func main() {
	fmt.Println(Parity(7))
}

alt:
package main

import "fmt"

func Parity(n int) string {
	switch n % 2 {
	case 0:
		return "even"
	default:
		return "odd"
	}
}

func main() {
	fmt.Println(Parity(7))
}
